// Does a benign op first (stamping the CPED context to THIS package), then
// polls the passed watcher. The poll op should attribute to poller-dep, whose
// principal != the watcher's owner (watcher-dep) -> denied under enforce.
export async function poll(watcher) {
  try { Deno.env.get("POLLER_MARK"); } catch { /* stamp attempt */ }
  try {
    for await (const _e of watcher) { return "got-event"; }
    return "ended";
  } catch (e) {
    return "denied:" + e.name;
  }
}
